// --- list_resources ---

// listResourcesArgs takes the kind two ways on purpose. Kind ("Deployment")
// is the form advertised to the model, because enumeration is the one place
// where a caller genuinely does not know the object yet and asking it to
// spell out an apiVersion it never read anywhere is friction for no gain.
// GVK ("apps/v1/Deployment") is accepted as well, unadvertised, for the two
// callers that already hold one: internal code building a call from a
// Finding.GVK (internal/tunnel.Finding), and a model that has just made four
// other tool calls in this file's "[group/]version/Kind" convention and
// reasonably assumes the fifth works the same way. Rejecting that guess would
// cost a turn out of a bounded investigation to teach nothing.
type listResourcesArgs struct {
	Kind          string `json:"kind,omitempty"`
	GVK           string `json:"gvk,omitempty"`
	Namespace     string `json:"namespace,omitempty"`
	LabelSelector string `json:"labelSelector,omitempty"`
	Limit         int    `json:"limit,omitempty"`
}

// listResourceItem is the compact per-object projection — deliberately NOT
// the object. describe_resource already returns full spec/status for an
// object you can name; this tool's entire job is to let a caller find out
// which names exist, so returning anything close to a full object per item
// would burn the model's context on 50 objects it is about to discard 49 of.
//
// Namespace is absent by design: it is fixed for the whole call (a namespaced
// kind requires exactly one namespace, a cluster-scoped one has none), so it
// is carried once on listResourcesResult instead of repeated on every item.
// Phase and Ready are the two status-ish fields that are both cheap to derive
// and the actual reason a caller enumerates — "the Deployment exists but is
// 0/3 ready" answers the question, whereas a bare name list only tells you to
// go make another call.
type listResourceItem struct {
	Name              string    `json:"name"`
	CreationTimestamp time.Time `json:"creationTimestamp"`
	// CreationTimestampSecondsSince is BACKLOG.md C9's precomputed relative
	// value (relative_time.go) for this same field — see describe_resource's
	// use of annotateRelativeTimestamps for the general mechanism this is the
	// typed-struct equivalent of.
	CreationTimestampSecondsSince int64  `json:"creationTimestampSecondsSince"`
	Phase                         string `json:"phase,omitempty"`
	Ready                         string `json:"ready,omitempty"`
	// Facts: state_facts.go's sentences, for reviewed kinds only.
	Facts []string `json:"facts,omitempty"`
}

// listResourcesResult reports the truncation state in the payload itself, not
// only through Execute's truncated return value. That is not redundancy: the
// wire-level ToolResult.Truncated flag is dropped on the way to the model —
// internal/gateway.CallTool returns result.Data alone, and both the api
// backend (internal/api/analyze.go) and the MCP surface (internal/mcp) hand
// the model that Data and nothing else. A flag the model never sees cannot
// stop it concluding from absence, so the honest signal has to live inside
// the JSON: Truncated says a window was cut, TotalMatched says how wide the
// real result was, and Returned says how much of it is here.
//
// GVK is echoed back in this file's "[group/]version/Kind" convention so a
// caller that asked by bare kind can feed the result straight into
// describe_resource/get_owner_chain/get_gitops_ownership without having to
// know how to spell the apiVersion.
type listResourcesResult struct {
	GVK          string             `json:"gvk"`
	Namespace    string             `json:"namespace,omitempty"`
	Items        []listResourceItem `json:"items"`
	Returned     int                `json:"returned"`
	TotalMatched int                `json:"totalMatched"`
	Truncated    bool               `json:"truncated"`
}

// resolveListKind turns listResourcesArgs' two kind spellings into one GVK.
// The explicit gvk wins when both are present — it is the unambiguous form,
// so honoring it needs no tie-break rule.
//
// A bare Kind name is checked against listableKindsByName (supportedGVKs)
// first and then, for BACKLOG.md E13, against the discovered watch set too —
// a caller enumerating a kind found only via discovery has just as much
// reason to prefer the friendlier bare-Kind form as one enumerating a
// supportedGVKs kind, and there is no reason to make it spell out an
// apiVersion for that alone. Ambiguity is judged across the UNION of both
// sources, matching listableKindsByName's own doc comment on why this is a
// slice per name rather than a single value.
func resolveListKind(ctx context.Context, args listResourcesArgs) (schema.GroupVersionKind, error) {
	if args.GVK != "" {
		return parseGVKString(args.GVK)
	}
	if args.Kind == "" {
		return schema.GroupVersionKind{}, errors.New("kind is required")
	}
	candidates := append([]schema.GroupVersionKind(nil), listableKindsByName[args.Kind]...)
	if wsc := discoveredWatchSetCache.Load(); wsc != nil {
		discovered, err := wsc.Get(ctx)
		if err != nil {
			logger.WarnContext(ctx, "list_resources: discovered watch set unavailable, resolving kind against supportedGVKs only", slog.String("kind", args.Kind), logging.Err(err))
		} else {
			for dgvk := range discovered {
				if dgvk.Kind != args.Kind {
					continue
				}
				if _, alreadySupported := supportedGVKs[dgvk]; alreadySupported {
					// Already in candidates via listableKindsByName —
					// counting it again would manufacture a fake ambiguity
					// out of one kind found through both sources.
					continue
				}
				candidates = append(candidates, dgvk)
			}
		}
	}
	switch len(candidates) {
	case 1:
		return candidates[0], nil
	case 0:
		return schema.GroupVersionKind{}, fmt.Errorf("unsupported kind %q; supported kinds are: %s", args.Kind, supportedKindNames())
	default:
		return schema.GroupVersionKind{}, fmt.Errorf("kind %q is ambiguous across more than one API group; pass gvk (\"[group/]version/Kind\") instead", args.Kind)
	}
}

// listResources enumerates one supported kind, which is the capability the
// other five tools left missing: every one of them requires a name the caller
// already has, so the investigation loop could describe an object it was
// handed but could not answer "does this even exist?" or "what else is in
// here?". WORKLOG.md §86 is the measured consequence — an investigation into
// a 156-day-stuck PVC had to conclude with "the workload either was never
// deployed, was deleted, or is in a different namespace" because listing the
// namespace's Deployments was not something it could do. CAPABILITIES.md
// §2 records the same gap.
//
// Read-only, and inside the existing RBAC with no chart change: every kind in
// supportedGVKs is already covered by argus-investigate's get/list/watch
// grants (deploy/helm/argus-agent/templates/clusterrole.yaml — verified line
// by line against this map, and independently true by construction because
// sweep_detector.go already Lists deployments, statefulsets, daemonsets,
// persistentvolumeclaims, jobs, nodes, horizontalpodautoscalers, services and
// endpointslices on every sweep). This adds no verb the agent did not already
// hold; it only exposes an existing one to the investigation loop.
func (e *ToolExecutor) listResources(ctx context.Context, rawArgs json.RawMessage) (json.RawMessage, bool, error) {
	var args listResourcesArgs
	if err := json.Unmarshal(rawArgs, &args); err != nil {
		return nil, false, fmt.Errorf("invalid args: %w", err)
	}
	gvk, err := resolveListKind(ctx, args)
	if err != nil {
		return nil, false, err
	}
	// See resolveDescribableResource's own doc comment (BACKLOG.md E13): this
	// checks supportedGVKs first, then the same discovered watch set
	// generic_predicates.go already unions into detection. reviewed decides
	// which per-item projection below is safe to use.
	res, reviewed, err := e.resolveDescribableResource(ctx, gvk)
	if err != nil {
		return nil, false, err
	}
	// Secret is supported for a single named describe_resource lookup only
	// (see supportedGVKs' own comment on that entry) — never for
	// enumeration. Refused explicitly, before the List call is even built,
	// rather than left to fail on an RBAC 403: clusterrole.yaml deliberately
	// grants "get" on secrets and nothing else, precisely so this agent
	// never lists every Secret in a namespace at once, and a clear refusal
	// here says that in the one place a caller would otherwise have to infer
	// it from a generic permission-denied error.
	if gvk == secretGVK {
		return nil, false, errors.New("list_resources does not support Secret — use describe_resource with a specific name instead; this agent is deliberately not granted list/watch on secrets")
	}
	// Same order as describeResource: the kind decides whether a namespace is
	// required at all, so this can only be checked once the kind resolved.
	// Deliberately NOT relaxed to "omit namespace to list across all
	// namespaces" — a cluster-wide Pod list is precisely the unbounded case
	// the caps below exist to prevent, and a caller that needs to search
	// several namespaces should say which ones, one call each, rather than
	// have this tool quietly fan out across the whole cluster on its behalf.
	if err := requireNamespaceFor(res, args.Namespace); err != nil {
		return nil, false, err
	}

	limit := args.Limit
	if limit <= 0 {
		limit = defaultListLimit
	}
	if limit > maxListLimit {
		limit = maxListLimit
	}

	listOpts := metav1.ListOptions{}
	if args.LabelSelector != "" {
		// Parsed here rather than handed to the API server unvalidated: a
		// malformed selector comes back as a generic 400 that sanitizeK8sErr
		// (correctly) flattens to "kubernetes API request failed", which tells
		// the caller nothing about which half of its own request was wrong.
		// The parse error only ever describes the caller's own input, so it is
		// safe to return verbatim under this file's error-hygiene rule.
		sel, err := labels.Parse(args.LabelSelector)
		if err != nil {
			return nil, false, fmt.Errorf("invalid labelSelector %q: %w", args.LabelSelector, err)
		}
		listOpts.LabelSelector = sel.String()
	}

	// The selector is pushed down to the API server; the limit deliberately is
	// NOT. ListOptions.Limit would make the server stop early and hand back a
	// continue token, at which point TotalMatched could only ever be "at least
	// this many" — and a floor is not a total. Since the whole point of the
	// truncation contract is that the caller learns the true size of what it
	// did not see, this fetches the matched set and windows it here. The cost
	// is bounded by what this process already does on a timer: sweep_detector.go
	// Lists these same kinds across ALL namespaces on every sweep, so a
	// single-namespace list is strictly cheaper than the agent's existing
	// steady-state memory profile.
	list, err := e.resourceInterface(res, args.Namespace).List(ctx, listOpts)
	if err != nil {
		return nil, false, sanitizeK8sErr(err)
	}

	// One now() snapshot for every item this call projects (BACKLOG.md C9) —
	// same reasoning as getEvents' own now := time.Now().UTC() above.
	now := time.Now().UTC()
	items := make([]listResourceItem, 0, len(list.Items))
	for i := range list.Items {
		if reviewed {
			items = append(items, projectListItem(&list.Items[i], now))
		} else {
			// BACKLOG.md E13: gvk resolved only through discovery. See
			// projectListItemAggressive's own doc comment for why this
			// tool's compact projection cannot reuse projectListItem's
			// Phase/Ready heuristics for a schema nobody has reviewed.
			items = append(items, projectListItemAggressive(&list.Items[i], now))
		}
	}
	// Sorted by name before windowing, because API server list order is not
	// contractually stable: without this, two identical calls against an
	// unchanged cluster could return different halves of the same set, and a
	// caller comparing them would "discover" churn that never happened.
	sort.Slice(items, func(i, j int) bool { return items[i].Name < items[j].Name })

	total := len(items)
	truncated := false
	if total > limit {
		items = items[:limit]
		truncated = true
	}

	return mustMarshal(listResourcesResult{
		GVK:          formatGVK(gvk),
		Namespace:    args.Namespace,
		Items:        items,
		Returned:     len(items),
		TotalMatched: total,
		Truncated:    truncated,
	}), truncated, nil
}

// projectListItem reduces one live object to listResourceItem. Driven by which
// fields the object actually carries rather than by a switch on Kind, so a
// kind added to supportedGVKs later gets whatever readiness/phase signal it
// happens to expose for free, instead of silently returning a bare name until
// someone remembers to add a case here.
func projectListItem(obj *unstructured.Unstructured, now time.Time) listResourceItem {
	created := obj.GetCreationTimestamp().Time
	item := listResourceItem{
		Name:                          obj.GetName(),
		CreationTimestamp:             created,
		CreationTimestampSecondsSince: secondsSince(created, now),
	}
	// status.phase covers Pod, PersistentVolumeClaim and PersistentVolume —
	// which is most of what a caller enumerating a broken namespace is after.
	item.Phase, _, _ = unstructured.NestedString(obj.Object, "status", "phase")
	item.Ready = listItemReady(obj)
	item.Facts = stateFacts(obj, now)
	return item
}

// projectListItemAggressive is projectListItem's counterpart for a kind
// resolved only through discovery (BACKLOG.md E13) — an unreviewed CRD.
// Name and CreationTimestamp come straight from metadata, the same identity
// fields resolveDescribableResource/redact.AggressiveObject already treat as
// safe to show verbatim for any kind, reviewed or not.
//
// Phase and Ready are deliberately NOT computed here, unlike projectListItem.
// That function's readiness heuristics read status.phase / status.replicas /
// status.conditions on the assumption that those paths mean, on this object,
// what they mean on the ~30 kinds this file was written against — an
// assumption this codebase can only make for a reviewed kind. list_resources'
// compact projection has no redaction pass of its own the way
// describe_resource's object does (it is a hand-built projection, not
// arbitrary JSON piped through redact.AggressiveObject), so the only safe
// default for an arbitrary CRD's status shape is not reading it at all —
// list_resources still answers "does this named object exist" and "when was
// it created," which is what BACKLOG.md E13 asks this tool to unlock for an
// unreviewed kind; describe_resource remains the tool for anything past
// that, with AggressiveObject actually filtering what it reads.
func projectListItemAggressive(obj *unstructured.Unstructured, now time.Time) listResourceItem {
	created := obj.GetCreationTimestamp().Time
	return listResourceItem{
		Name:                          obj.GetName(),
		CreationTimestamp:             created,
		CreationTimestampSecondsSince: secondsSince(created, now),
	}
}

// listItemReady derives a compact readiness string from whichever of the four
// mutually-exclusive shapes Kubernetes uses for the same idea. Ordering
// matters: a Pod carries both containerStatuses AND a Ready condition, and the
// container tally ("1/2") is the more useful of the two, so it is checked
// first. Returns "" when the object has no readiness notion at all (a Service,
// a StorageClass) — omitempty then keeps the field off the wire entirely
// rather than emitting a misleading empty value.
func listItemReady(obj *unstructured.Unstructured) string {
	if statuses, found, _ := unstructured.NestedSlice(obj.Object, "status", "containerStatuses"); found {
		ready := 0
		for _, raw := range statuses {
			cs, ok := raw.(map[string]any)
			if !ok {
				continue
			}
			if isReady, _ := cs["ready"].(bool); isReady {
				ready++
			}
		}
		return fmt.Sprintf("%d/%d", ready, len(statuses))
	}
	// DaemonSet: no replicas field at all, its own pair of counters instead.
	if desired, found, _ := unstructured.NestedInt64(obj.Object, "status", "desiredNumberScheduled"); found {
		ready, _, _ := unstructured.NestedInt64(obj.Object, "status", "numberReady")
		return fmt.Sprintf("%d/%d", ready, desired)
	}
	// Deployment/ReplicaSet/StatefulSet. status.replicas is preferred over
	// spec.replicas (it's what the controller actually observed) but is absent
	// on an object the controller has not reconciled yet — exactly the case a
	// caller investigating a never-started workload is looking at — so
	// spec.replicas is the fallback rather than the primary.
	total, found, _ := unstructured.NestedInt64(obj.Object, "status", "replicas")
	if !found {
		total, found, _ = unstructured.NestedInt64(obj.Object, "spec", "replicas")
	}
	if found {
		// readyReplicas is omitempty in the API types, so "absent" and "zero"
		// are the same fact here; 0 is the correct reading of both.
		ready, _, _ := unstructured.NestedInt64(obj.Object, "status", "readyReplicas")
		return fmt.Sprintf("%d/%d", ready, total)
	}
	// Node, and anything else whose readiness is a condition.
	if conditions, found, _ := unstructured.NestedSlice(obj.Object, "status", "conditions"); found {
		for _, raw := range conditions {
			cond, ok := raw.(map[string]any)
			if !ok {
				continue
			}
			if condType, _ := cond["type"].(string); condType == "Ready" {
				status, _ := cond["status"].(string)
				return status
			}
		}
	}
	return ""
}
